mapper.select:
SELECT id, business_type, batch_no, original_file_name, file_size, file_sha256, total_rows, total_shipments, success_count, failed_count, status, operator, error_message, upload_time, start_time, finish_time, duration_ms, create_time, update_time FROM customs_shipment_fee_import_batch
AND business_type = #{businessType}
AND batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND status = #{status}
AND operator LIKE CONCAT('%', #{operator}, '%')
ORDER BY id DESC
